def maxSumWithDeletions(nums, k):
    NEG = float("-inf")
    E = [NEG] * (k + 1)
    D = [NEG] * (k + 1)
    best = NEG
    for i, x in enumerate(nums):
        nE = [NEG] * (k + 1)
        nD = [NEG] * (k + 1)
        for j in range(k + 1):
            prev = max(E[j], D[j])
            if j == 0:
                prev = max(prev, 0)
            nE[j] = x + prev
            if j >= 1:
                nD[j] = max(E[j - 1], D[j - 1])
            if nE[j] > best:
                best = nE[j]
        E, D = nE, nD
    return best
